package fi.alavesa.radio.hud;

import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.TextComponent;
import net.kyori.adventure.text.format.ShadowColor;
import net.kyori.adventure.text.format.TextColor;

/**
 * Lays the radio popup out inside ONE text component (the name of a boss bar).
 *
 * <p>How it works (fonts radio:hud and radio:bold, generated by tools/GenFont.java + tools/gen_pack.py;
 * shaders/include/radio_text_*.glsl):
 * <ul>
 *   <li>every character of the fonts advances exactly {@link #ADVANCE} px (monospace by construction), and the font
 *       has signed spaces of ±2^n px, so the pen can be put anywhere - also between character cells, which is how
 *       the tab pill slides smoothly;</li>
 *   <li>the component always ends with the pen back at 0: its width is 0, so the client's centring puts pen 0 at
 *       the screen centre, and the text shader moves every glyph from there into the corner;</li>
 *   <li>the text colour is the marker #FEFBxx: blue bits 0-3 = row (15 = panel art, 14 = tab pill), bits 4-6 =
 *       palette or art flags. Shadows are off, or a dark copy of every glyph would stay behind at the top.</li>
 * </ul>
 * The geometry constants mirror tools/gen_pack.py.
 */
public final class HudText {

    public static final Key FONT = Key.key("radio", "hud");
    public static final Key BOLD = Key.key("radio", "bold");
    public static final int ADVANCE = 8;
    /** Characters per row. */
    public static final int COLUMNS = 24;
    /** Rows: header, tab strip, {@link #MESSAGE_LINES} message rows, footer. */
    public static final int ROW_HEADER = 0, ROW_TABS = 1, ROW_MESSAGES = 2, MESSAGE_LINES = 5, ROW_FOOTER = 7;
    /** The tab strip shows this many tabs of {@link #TAB_COLUMNS} columns each. */
    public static final int TAB_COUNT = 4, TAB_COLUMNS = 6;
    public static final int WHITE = 0, AMBER = 1, CYAN = 2, GREY = 3, DIM = 4, GREEN = 5, RED = 6, YELLOW = 7;
    /** Art flags. */
    public static final int PANEL = 0, PANEL_STATIC = 1, LAMP = 2;

    // the icons of the font sheet (tools/GenFont.java)
    public static final char DOT = '\uE100', ARROW = '\uE101', BLOCK = '\uE102', SIGNAL = '\uE110' /* + 0..3 */, SEGMENT = '\uE120',
            LEFT = '\uE121', RIGHT = '\uE122', UNREAD = '\uE123', TX = '\uE124', RX = '\uE125';

    public static final int TEXT_X = 8, PANEL_W = 208, PILL_W = 46;
    private static final int ART_ROW = 15, PILL_ROW = 14, LAMP_X = 178, LAMP_W = 22;
    private static final char CHAR_PANEL = '\uE010', CHAR_LAMP = '\uE011', CHAR_PILL = '\uE012';
    private static final char SPACE_POS = '\uF000', SPACE_NEG = '\uF100';
    /** What the font sheet has besides ASCII 0x20-0x7E. */
    private static final String EXTRA = "äöåÄÖÅüÜéÉèñß°·•€£¡¿";

    /** The RGB palette of radio_text_fragment.glsl, for picking the nearest entry to a channel's colour. */
    private static final int[] PALETTE_RGB = {0xF0F5FC, 0xFFBA3D, 0x73E0FF, 0x9EABBD, 0x5C697D, 0x6BFF94, 0xFF6157, 0xFFED73};

    private final List<Component> parts = new ArrayList<>();
    private int pen;

    /** The panel background; {@code incoming} adds static while a transmission comes in. Call first. */
    public HudText panel(boolean incoming) {
        return art(0, CHAR_PANEL, PANEL_W, ART_ROW, incoming ? PANEL_STATIC : PANEL);
    }

    /** The lit TX/RX lamp in the header. */
    public HudText lamp() {
        return art(LAMP_X, CHAR_LAMP, LAMP_W, ART_ROW, LAMP);
    }

    /** The active tab's pill, with its left edge at {@code x} px (any pixel: it slides). Draw before the tab labels. */
    public HudText pill(int x) {
        return art(x, CHAR_PILL, PILL_W, PILL_ROW, 0);
    }

    private HudText art(int x, char glyph, int width, int row, int flags) {
        parts.add(Component.text(shift(x - pen) + glyph, marker(row, flags)).font(FONT).shadowColor(ShadowColor.none()));
        pen = x + width + 1;
        return this;
    }

    /** Text with its left edge at a pixel x, in the regular or bold face. */
    public HudText at(int row, int x, String text, int palette, boolean bold) {
        String s = sanitize(text);
        if (s.isEmpty()) return this;
        parts.add(Component.text(shift(x - pen), marker(row, palette)).font(FONT).shadowColor(ShadowColor.none()));
        parts.add(Component.text(s, marker(row, palette)).font(bold ? BOLD : FONT).shadowColor(ShadowColor.none()));
        pen = x + s.length() * ADVANCE;
        return this;
    }

    /** Icon characters ({@link #DOT} etc.), in the regular face only. */
    public HudText icon(int row, int x, char icon, int palette) {
        parts.add(Component.text(shift(x - pen) + icon, marker(row, palette)).font(FONT).shadowColor(ShadowColor.none()));
        pen = x + ADVANCE;
        return this;
    }

    /** Text starting at a column (0 = the left text edge). It is cut at the right edge. */
    public HudText text(int row, int column, String text, int palette) {
        return column(row, column, text, palette, false);
    }

    public HudText bold(int row, int column, String text, int palette) {
        return column(row, column, text, palette, true);
    }

    private HudText column(int row, int column, String text, int palette, boolean bold) {
        String s = sanitize(text);
        if (column < 0 || column >= COLUMNS || s.isEmpty()) return this;
        if (s.length() > COLUMNS - column) s = s.substring(0, COLUMNS - column);
        return at(row, TEXT_X + column * ADVANCE, s, palette, bold);
    }

    /** Text ending at the right edge of the text area. */
    public HudText right(int row, String text, int palette) {
        String s = sanitize(text);
        if (s.length() > COLUMNS) s = s.substring(0, COLUMNS);
        return text(row, COLUMNS - s.length(), s, palette);
    }

    public Component build() {
        TextComponent.Builder out = Component.text();
        for (Component part : parts) out.append(part);
        // back to pen 0: the whole component is then 0 px wide (see the class comment)
        out.append(Component.text(shift(-pen)).font(FONT));
        return out.build();
    }

    private static TextColor marker(int row, int data) {
        return TextColor.color(254, 251, (row & 15) | ((data & 7) << 4));
    }

    private static String shift(int px) {
        StringBuilder out = new StringBuilder();
        char base = px < 0 ? SPACE_NEG : SPACE_POS;
        int n = Math.abs(px);
        for (int bit = 9; bit >= 0; bit--) if ((n & (1 << bit)) != 0) out.append((char) (base + bit));
        return out.toString();
    }

    /**
     * What the popup fonts can show: ASCII, a few accented letters and symbols. Curly quotes and dashes become plain
     * ones; anything else becomes '?'. So every character is exactly one cell wide.
     */
    public static String sanitize(String text) {
        StringBuilder out = new StringBuilder(text.length());
        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (ch >= 0x20 && ch < 0x7F || EXTRA.indexOf(ch) >= 0) out.append(ch);
            else if (ch == '`' || ch == '´' || ch == '’' || ch == '‘') out.append('\'');
            else if (ch == '–' || ch == '—') out.append('-');
            else if (ch == '“' || ch == '”') out.append('"');
            else if (ch == '…') out.append("..");
            else if (ch == '\n' || ch == '\t') out.append(' ');
            else if (ch >= 0xE000 && ch < 0xF900) out.append('?');   // private use: never let a player type an icon
            else if (!Character.isLowSurrogate(ch) && !Character.isISOControl(ch)) out.append('?');
        }
        return out.toString();
    }

    /** The palette entry closest to an RGB colour (for channel names). */
    public static int nearestPalette(int rgb) {
        int best = WHITE;
        long bestDistance = Long.MAX_VALUE;
        for (int i = 0; i < PALETTE_RGB.length; i++) {
            if (i == DIM || i == GREY) continue; // too faint for a name
            long dr = ((rgb >> 16) & 255) - ((PALETTE_RGB[i] >> 16) & 255), dg = ((rgb >> 8) & 255) - ((PALETTE_RGB[i] >> 8) & 255),
                    db = (rgb & 255) - (PALETTE_RGB[i] & 255);
            long d = dr * dr + dg * dg + db * db;
            if (d < bestDistance) {
                bestDistance = d;
                best = i;
            }
        }
        return best;
    }

    /**
     * Breaks text into rows: the first row has {@code first} columns, the others {@code rest}; the caller indents the
     * continuation rows. Words are not split unless one is longer than a row.
     */
    public static List<String> wrap(String text, int first, int rest) {
        List<String> lines = new ArrayList<>();
        String remaining = sanitize(text).strip();
        int width = first;
        while (!remaining.isEmpty()) {
            if (remaining.length() <= width) {
                lines.add(remaining);
                break;
            }
            int cut = remaining.lastIndexOf(' ', width);
            if (cut < width / 2) cut = width; // a very long word: cut it
            lines.add(remaining.substring(0, cut).stripTrailing());
            remaining = remaining.substring(cut).stripLeading();
            width = rest;
        }
        return lines;
    }
}
